// Render offline with the original full-surface shader; output 4-bit alpha for indexed PNG encoding.
const fs = require('node:fs');
const http = require('node:http');
const { chromium } = require(process.env.GLASSLIGHT_PLAYWRIGHT || 'playwright');
(async () => {
	const server = http.createServer((request, response) => {
		if (request.url === '/mesh') { response.setHeader('Content-Type', 'application/octet-stream'); fs.createReadStream(process.argv[2]).pipe(response); }
		else { response.setHeader('Content-Type', 'text/html'); response.end('<!doctype html><title>Offline model renderer</title>'); }
	});
	await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
	const browser = await chromium.launch({ executablePath: process.env.GLASSLIGHT_BROWSER, headless: true });
	try {
		const page = await browser.newPage();
		await page.goto('http://127.0.0.1:' + server.address().port);
		const alpha = await page.evaluate(async () => {
			const bytes = new Uint8Array(await (await fetch('/mesh')).arrayBuffer());
			const canvas = document.createElement('canvas');
			canvas.width = 3200; canvas.height = 2000;
			const gl = canvas.getContext('webgl2', {alpha: true, antialias: true, preserveDrawingBuffer: true});
			if (!gl) throw Error('WebGL2 unavailable');
			const program = gl.createProgram();
			for (const [type, source] of [[gl.VERTEX_SHADER, `#version 300 es
			in vec3 position; out vec3 surface;
			void main() { vec3 p = position * (32767.0 / 60000.0); surface = p; gl_Position = vec4(p.x*1.76, p.z*2.816, p.y, 1.0); }`],
			[gl.FRAGMENT_SHADER, `#version 300 es
			precision highp float; in vec3 surface; out vec4 outputColor;
			void main() { vec3 cell = floor(surface*4800.0); float seed = fract(sin(dot(cell,vec3(12.9898,78.233,37.719)))*43758.5453);
			if (seed > .22) discard; float dotLight = .48 + .24*seed/.22; outputColor = vec4(vec3(dotLight),dotLight); }`]]) {
				const shader = gl.createShader(type); gl.shaderSource(shader, source); gl.compileShader(shader);
				if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) throw Error(gl.getShaderInfoLog(shader));
				gl.attachShader(program, shader);
			}
			gl.linkProgram(program);
			if (!gl.getProgramParameter(program, gl.LINK_STATUS)) throw Error(gl.getProgramInfoLog(program));
			gl.useProgram(program);
			gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer()); gl.bufferData(gl.ARRAY_BUFFER, bytes, gl.STATIC_DRAW);
			const position = gl.getAttribLocation(program, 'position');
			gl.enableVertexAttribArray(position); gl.vertexAttribPointer(position, 3, gl.SHORT, true, 0, 0);
			gl.viewport(0, 0, 3200, 2000); gl.disable(gl.DEPTH_TEST); gl.enable(gl.BLEND); gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
			gl.clearColor(0,0,0,0); gl.clear(gl.COLOR_BUFFER_BIT); gl.drawArrays(gl.TRIANGLES, 0, bytes.length / 6);
			if (gl.getError() !== gl.NO_ERROR) throw Error('Model render failed');
			const small = document.createElement('canvas'); small.width = 1600; small.height = 1000;
			const ctx = small.getContext('2d'); ctx.drawImage(canvas, 0, 0, 1600, 1000);
			const rgba = ctx.getImageData(0, 0, 1600, 1000).data;
			const parts = [];
			for (let start = 0; start < 1600000; start += 8192) {
				let part = '';
				for (let i = start; i < Math.min(start + 8192, 1600000); i++) part += String.fromCharCode(Math.round(rgba[i*4+3]/17));
				parts.push(part);
			}
			return btoa(parts.join(''));
		});
		fs.writeFileSync(process.argv[3], Buffer.from(alpha, 'base64'));
	} finally { await browser.close(); server.close(); }
})().catch(error => { console.error(error); process.exitCode = 1; });
